import React, { useState } from 'react';

import * as ToggleGroupPrimitive from '@radix-ui/react-toggle-group';
import { omitTransientProps } from 'utils/emotion';

import {
  StyledGroup,
  StyledItem,
  StyledLabel,
} from './SegmentedControl.styles';
import type { SegmentedControlProps } from './SegmentedControl.types';

export const SegmentedControl = React.forwardRef<
  React.ElementRef<typeof ToggleGroupPrimitive.Root>,
  SegmentedControlProps
>(
  (
    {
      defaultValue,
      disabled,
      onValueChange,
      options,
      value: controlledValue,
      ...props
    },
    forwardedRef,
  ) => {
    const [uncontrolledValue, setUncontrolledValue] = useState(
      defaultValue ?? options[0]?.value,
    );
    const isControlled = controlledValue !== undefined;
    const currentValue = isControlled ? controlledValue : uncontrolledValue;

    if (options.length < 2 || options.length > 3) {
      // eslint-disable-next-line no-console
      console.warn('Options length must be equal to 2 or 3.');
      return <></>;
    }

    const handleValueChange = (nextValue: string) => {
      if (!nextValue) {
        return;
      }

      if (!isControlled) {
        setUncontrolledValue(nextValue);
      }

      onValueChange?.(nextValue);
    };

    return (
      <ToggleGroupPrimitive.Root
        {...omitTransientProps(props)}
        ref={forwardedRef}
        disabled={disabled}
        onValueChange={handleValueChange}
        orientation="horizontal"
        type="single"
        value={currentValue}
        asChild
      >
        <StyledGroup>
          {options.map((option) => (
            <ToggleGroupPrimitive.Item
              key={option.value}
              asChild
              disabled={option.disabled}
              value={option.value}
            >
              <StyledItem type="button">
                <StyledLabel>{option.label}</StyledLabel>
              </StyledItem>
            </ToggleGroupPrimitive.Item>
          ))}
        </StyledGroup>
      </ToggleGroupPrimitive.Root>
    );
  },
);

SegmentedControl.displayName = 'SegmentedControl';
